            },
            "layers": [
              {
                "material": "sio2",
                "thickness_nm": 80.0,
                "coherence": "coherent",
                "optimizable": true,
                "min_thickness_nm": 40.0,
                "max_thickness_nm": 160.0,
                "label": "layer_1"
              },
              {
                "material": "tio2",
                "thickness_nm": 80.0,
                "coherence": "coherent",
                "optimizable": true,
                "min_thickness_nm": 40.0,
                "max_thickness_nm": 160.0,
                "label": "layer_2"
              }
            ],
            "exit": {
              "constant_n": 1.52,
              "constant_k": 0.0
            }
          },
          "spectrum": {
            "start_nm": 450.0,
            "stop_nm": 700.0,
            "points": 51
          },
          "illumination": {
            "angles_deg": [0.0],
            "polarizations": ["s"]
          },
          "solver": "smatrix",
          "allow_material_extrapolation": false,
          "requested_outputs": [
            "R",
            "T",
            "A"
          ],
          "physics": {
            "geometry_class": "layered_planar",
            "material_class": "isotropic",
            "excitation_class": "plane_wave",
            "time_domain_required": false
          }
        },
        "targets": [
          {
            "observable": "R",
            "target": 0.03,
            "wavelength_min_nm": 450.0,
            "wavelength_max_nm": 700.0,
            "weight": 1.0,
            "angle_deg": 0.0,
            "polarization": "s",
            "constraint": "at_most",
            "aggregation": "mean",
            "name": "minimize_mean_reflectance_450_700"
          }
        ],
        "optimizer": {
          "method": "adam_lbfgs",
          "max_steps": 64,
          "learning_rate": 0.05,
          "starts": 3,
          "seed": 17,
          "early_stop_patience": 15,
          "improvement_tolerance": 1e-7,
          "gradient_clip_norm": 10.0,
          "thickness_window_nm": 100.0,
          "quantization_nm": 1.0
        }
      },
      "objectives": [
        {
          "objective_id": "obj_mean_r_450_700",
          "metric": "mean_reflectance",
          "sense": "minimize",
          "weight": 1.0,
          "target": null,
          "region": {
            "wavelength_nm": [
              450.0,
              700.0
            ]
          },
          "admission_role": "score_only"
        }
      ],
      "tags": [
        "ar_coating",
        "two_layer",
        "s_polarized"
      ]
    }
  ],
  "uncertainty": {
    "thickness_sigma_nm": 1.0,
    "thickness_error_model": "absolute_normal",
    "thickness_relative_fraction": 0.0,
    "thickness_samples": 16,
    "angle_perturbation_deg": 0.0,
    "material_dataset_policy": "resolved_only",
    "maximum_material_scenarios": 8,
    "random_seed": 42
  }
}

